function xsel=xlsheet(r1,z1,r2,z2,nh)% function xsel=xlsheet(r1,z1,r2,z2,nh)% Self-inductance of a current sheet with end points (r1,z1) and (r2,z2)% Gribov-Portone, Naka, 22/2/1997;%dbstop if errorif nh > 100,'stop subroutine lsheet: nh > 100', return; end;mu0 = 4e-7*pi;r   = r1+([1:nh]'-0.5)*(r2-r1)/nh;z   = z1+([1:nh]'-0.5)*(z2-z1)/nh;dl  = sqrt((r2-r1)*(r2-r1) + (z2-z1)*(z2-z1))/nh;xls = mu0*r.*(log(8*r/dl)-0.5);if nh==1;return;end;xlh = xring(r,z,r,z);xlh = tril(xlh,-2);xlk = 0.5*mu0*(r(2:length(r))+r(1:length(r)-1)).*(log((r(2:length(r))+r(1:length(r)-1))/dl)-0.5);xlk = diag(xlk,-1);xls = diag(xls)+xlk+xlk'+xlh+xlh';xsel= sum(sum(abs(xls)))/nh^2;return